function moderatorVacancies(el){const div=document.createElement('section');div.className='plus-card';div.innerHTML=`<h2>Vacancy management</h2><p class="plus-muted">Mark confirmed unavailable roles for review. Saved applications remain intact. Automated link checks are only signals, not proof a role has closed.</p><div class="discover-toolbar"><input placeholder="Search by role or company" aria-label="Search vacancies for moderation"></div><div class="discover-list" id="dx-mod-jobs"></div>`;el.append(div);const input=div.querySelector('input'),out=div.querySelector('#dx-mod-jobs');const draw=()=>{const q=input.value.toLowerCase();const jobs=hJobs().filter(j=>[j.company,j.title].join(' ').toLowerCase().includes(q)).sort((a,b)=>Number(publicFlags.has(b.id)||b.linkStatus)-Number(publicFlags.has(a.id)||a.linkStatus));out.innerHTML=jobs.slice(0,40).map(j=>`<article><b>${e(j.company)} · ${e(j.title)}</b><p>${e(j.linkStatus||'')} ${publicFlags.has(j.id)?'Reported unavailable':''}</p>${btn(publicFlags.has(j.id)?'Clear warning':'Mark unavailable','dx-flag-vacancy',j.id)}</article>`).join('')||empty('No matching vacancies')};input.oninput=draw;draw()}
