async function renderCommunity(t=communityTab){if(!readyAuth()&&typeof careerFeedbackRender==='function')return careerFeedbackRender();communityTab=t;screen='community';shell(`${hHead('Community & feedback','Share general recruitment experiences and learn from others, without sharing personal information.')}<div class="journey-tabs">${[['browse','Community'],['submit','Contribute'],['reports','Report a vacancy'],['admin','Moderation']].map(([id,label])=>`<button class="hub-tab ${t===id?'active':''}" data-act="dx-community-tab" data-id="${id}">${label}</button>`).join('')}</div><div id="dx-community" class="discover-community"></div>`);const el=document.querySelector('#dx-community');if(t==='submit'||t==='reports'){drawCommunityForm(el,t==='reports');return}el.innerHTML=empty('Loading community…');const client=await initAccount();if(screen!=='community'||communityTab!==t||!el.isConnected)return;if(!client){el.innerHTML=card('Community access','<p>Community submissions and moderation are not available yet. Your other tools still work in guest mode.</p>');return}if(t==='admin'){if(!accountUser){el.innerHTML=card('Moderation','<p>Sign in with an authorised moderator account.</p>'+btn('Account','account'));return}const {data:role,error:roleError}=await client.rpc('career_is_moderator');if(screen!=='community'||!el.isConnected)return;if(roleError||!role){el.innerHTML=empty('Moderator access required.');return}const {data:rows,error}=await client.rpc('career_moderation_queue');if(screen!=='community'||!el.isConnected)return;if(error){el.innerHTML=empty('Moderation unavailable. Ask the site administrator to check configuration.');return}adminRows=rows||[];el.innerHTML=`<h2>Pending submissions and vacancy reports</h2><p class="plus-muted">Approve only anonymous, safe general experiences. Reject identifying details, contact information, harassment and confidential assessment content. Vacancy reports are for review, not public posts.</p><div class="discover-list">${adminRows.map(x=>`<article><b>${e(x.kind)} · ${e(x.employer)}</b><p>${e(x.body)}</p><p>${e(x.stage||'')} ${x.wait_days!==null?` · ${e(x.wait_days)} days`:''}</p><div class="journey-row">${x.kind!=='Vacancy report'?btn('Approve','dx-moderate',x.id,true):''}${btn(x.kind==='Vacancy report'?'Resolve report':'Reject','dx-reject',x.id)}</div></article>`).join('')||empty('No pending submissions.')}</div>`;await loadFlags();if(el.isConnected)moderatorVacancies(el);return}const {data:rows,error}=await client.rpc('career_public_community');if(!el.isConnected)return;if(error){el.innerHTML=empty('Community is temporarily unavailable.');return}communityRows=rows||[];drawCommunityList(el)}
function drawCommunityList(el){el.innerHTML=`<div class="discover-toolbar"><input id="dx-community-search" placeholder="Find employer or topic" aria-label="Search community"><select id="dx-community-kind" aria-label="Filter community"><option>All topics</option>${communityKinds.filter(k=>k!=='Vacancy report').map(k=>`<option>${e(k)}</option>`).join('')}</select>${btn('Contribute','dx-community-tab','submit',true)}</div><p class="plus-muted">Moderated anonymous experiences; not independently verified. No direct messages or public user profiles. Do not share confidential assessment questions.</p><div id="dx-community-rows" class="discover-list"></div>`;const draw=()=>{const q=el.querySelector('input').value.toLowerCase(),k=el.querySelector('select').value;const rows=communityRows.filter(r=>(k==='All topics'||r.kind===k)&&[r.employer,r.body,r.stage].join(' ').toLowerCase().includes(q));el.querySelector('#dx-community-rows').innerHTML=rows.map(r=>`<article><div class="discover-label">${e(r.kind)} · Anonymous</div><h3>${e(r.employer||'General advice')}</h3><p>${e(r.body)}</p><small>${e(r.stage||'')}${r.wait_days!=null?' · Reported wait: '+e(r.wait_days)+' days':''}${r.rating!=null?' · Reported rating: '+e(r.rating)+'/5':''}</small><div>${btn('Report content','dx-report-content',r.id)}</div></article>`).join('')||empty('No approved contributions match this search.')};el.querySelector('input').oninput=draw;el.querySelector('select').onchange=draw;draw()}
function drawCommunityForm(el,report=false,job=null){const kinds=report?['Vacancy report']:communityKinds.filter(k=>k!=='Vacancy report');el.innerHTML=card(report?'Report an incorrect or closed vacancy':'Share an anonymous contribution',`<p>Submissions require a signed-in account and are held for review. Do not include names of individuals, contact details, personal information, or actual confidential test questions.</p><form id="dx-community-form" class="hub-form">${nextSelect('Topic','kind',kinds.map(x=>[x,x]),kinds[0])}${formField('Employer or topic','employer',job?.company||'','text',true)}${formField('Recruitment stage (optional)','stage',job?.title||'')}${formField('Reported waiting time in days (optional)','wait_days','','number')}${nextSelect('Overall experience (optional)','rating',[['','Not rated'],[1,'1 / 5'],[2,'2 / 5'],[3,'3 / 5'],[4,'4 / 5'],[5,'5 / 5']],'')}${textArea(report?'Explain the issue and identify the role':'General experience or question','body',job?`${job.title}\n`: '')}<p class="plus-muted">Maximum 600 characters. No links, emails, phone numbers or contact requests.</p><label class="plus-check"><input name="consent" type="checkbox" required>I have removed personal and confidential information.</label><button class="hub-btn main-btn">Submit for review</button><p id="dx-community-status" role="status"></p></form>`);const form=el.querySelector('form');form.elements.body.maxLength=600;form.elements.body.required=true;form.elements.employer.maxLength=100;form.elements.stage.maxLength=100;form.elements.wait_days.min=0;form.elements.wait_days.max=365;form.onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(form)),status=form.querySelector('#dx-community-status');if(/https?:|www\.|@|\b\d{7,}\b/i.test([f.body,f.employer,f.stage].join(' '))){status.textContent='Remove links and contact details.';return}const client=await initAccount();if(!client||!accountUser){status.textContent='Please sign in before submitting.';return}form.querySelector('button').disabled=true;try{const {error}=await client.rpc('career_submit_community',{p_kind:f.kind,p_employer:f.employer,p_stage:f.stage,p_body:f.body,p_wait:f.wait_days===''?null:Number(f.wait_days),p_rating:f.rating===''?null:Number(f.rating),p_target:null});if(error)throw error;form.reset();status.textContent='Submitted for moderation.'}catch{status.textContent='Submission unavailable. Please try again later.'}finally{form.querySelector('button').disabled=false}}}
