// Private, opt-in cloud synchronisation with conflict protection.
function snapshot(){const b=plusBackup();delete b.exported;if(b.discover){b.discover={...b.discover};delete b.discover.sync}return b}
const hash=b=>{const s=JSON.stringify(b);let a=2166136261,c=0x9e3779b9;for(let i=0;i<s.length;i++){a=Math.imul(a^s.charCodeAt(i),16777619);c=Math.imul(c^s.charCodeAt(i),2246822519)}return `${s.length}:${a>>>0}:${c>>>0}`};
function syncMessage(s){const el=document.querySelector('#dx-sync-status');if(el)el.textContent=s}
async function syncTick(initial=false){if(syncBusy||!data.sync)return;syncBusy=true;try{const c=await initAccount();if(!c||!accountUser){syncMessage('Sign in to synchronise.');return}const id=accountUser.id;if(plusGet('discoverSyncOwner','')!==id){data.sync=false;save();syncMessage('Enable sync explicitly for this account.');return}if(syncOwner!==id){syncOwner=id;syncBase=plusGet('discoverSyncBase',null);syncHash=plusGet('discoverSyncHash','');if(!syncBase)initial=true}const {data:remote,error}=await c.from('career_hub_backups').select('payload,updated_at').eq('user_id',id).maybeSingle();if(error)throw error;let local=snapshot();const localHash=hash(local);if(initial&&remote){if(!confirm('Merge the existing private cloud backup into this browser and enable automatic sync?')){data.sync=false;save();return}restorePlus(remote.payload);data.sync=true;save();local=snapshot()}else if(remote&&syncBase&&remote.updated_at!==syncBase){if(localHash!==syncHash){data.sync=false;save();syncMessage('Sync paused: changes exist on both devices. Export a local backup and merge manually in Account.');addNotice('syncconflict:'+Date.now(),'Cloud sync paused','Changes exist on both devices. Back up and merge in Account.','account');return}restorePlus(remote.payload);data.sync=true;save();syncBase=remote.updated_at;syncHash=hash(snapshot());plusSet('discoverSyncBase',syncBase);plusSet('discoverSyncHash',syncHash);syncMessage('Updated from cloud.');return}else if(!initial&&localHash===syncHash){syncMessage('Up to date.');return}const now=new Date().toISOString(),payload={...local,exported:now};let write;if(remote){write=await c.from('career_hub_backups').update({payload,updated_at:now}).eq('user_id',id).eq('updated_at',remote.updated_at).select('updated_at').maybeSingle()}else{write=await c.from('career_hub_backups').insert({user_id:id,payload,updated_at:now}).select('updated_at').maybeSingle()}if(write.error||!write.data){data.sync=false;save();syncMessage('Sync paused: backup changed or unavailable. Use Account to resolve.');return}syncBase=write.data.updated_at;syncHash=hash(local);plusSet('discoverSyncBase',syncBase);plusSet('discoverSyncHash',syncHash);syncMessage('Last synced '+new Date(now).toLocaleTimeString('en-GB'))}catch{syncMessage('Sync unavailable; your local work is safe.')}finally{syncBusy=false}}
async function toggleSync(){if(data.sync){data.sync=false;save();renderAccount();return}const c=await initAccount();if(!c||!accountUser)return hToast('Sign in first');if(!confirm('Enable automatic private backups for this device? Existing cloud data will be merged on the first sync.'))return;data.sync=true;plusSet('discoverSyncOwner',accountUser.id);plusSet('discoverSyncBase',null);plusSet('discoverSyncHash','');save();await syncTick(true);if(screen==='account')renderAccount()}
