async function enablePush(){if(!('serviceWorker'in navigator)||!('PushManager'in window)||!plusConfig.vapidPublicKey)return hToast('Background notifications are not configured');const c=await initAccount();if(!c||!accountUser)return hToast('Sign in to enable background notifications');if(!confirm('Allow general notifications about newly discovered vacancies on this device? No personal application details are included.'))return;try{const p=await Notification.requestPermission();if(p!=='granted')return hToast('Notification permission not granted');const reg=await navigator.serviceWorker.getRegistration();if(!reg?.active)throw Error('No active service worker');const raw=plusConfig.vapidPublicKey.replace(/-/g,'+').replace(/_/g,'/');const applicationServerKey=Uint8Array.from(atob(raw.padEnd(Math.ceil(raw.length/4)*4,'=')),c=>c.charCodeAt(0));const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey});const {error}=await c.from('career_push_subscriptions').upsert({user_id:accountUser.id,endpoint:sub.endpoint,subscription:sub.toJSON()});if(error){await sub.unsubscribe();throw error}hToast('Background notifications enabled')}catch{hToast('Could not enable notifications. Check your browser and service configuration.')}}
